{
  "findings": [
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The ingress rule allows all protocols (port -1) from any source (0.0.0.0/0), which exposes the load balancer to unrestricted network traffic."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Ensure no security groups allow egress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The egress rule allows all protocols (port -1) to any destination (0.0.0.0/0), which permits unrestricted outbound traffic from the load balancer."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name   = \"allow-all-lb\"\n  vpc_id = data.aws_vpc.main.id\n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n  egress {\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"-1\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}",
  "fix_summary": "Restricted the ingress rule to only allow HTTPS (TCP port 443) traffic instead of allowing all protocols and ports from any source. The egress rule was left as-is because restricting it requires specific knowledge of the backend targets, but note that CKV_AWS_382 flags this; in a real-world scenario, you would restrict egress to the VPC CIDR or specific target group IPs."
}
